static AuthToken RequireToken(string? raw)
{
    if (string.IsNullOrWhiteSpace(raw))
        throw new ArgumentException("token missing", nameof(raw));
    return new AuthToken("sub", "iss", DateTimeOffset.UtcNow.AddHours(1));
}

try
{
    RequireToken(null);
}
catch (ArgumentException ex)
{
    Console.WriteLine(ex.Message);      // "token missing"
    Console.WriteLine(ex.StackTrace);   // frames from RequireToken upward
    Console.WriteLine(ex.ParamName);    // "raw" — ArgumentException detail
}

static bool TryGetScore(string id, out int score)
{
    if (!_cache.TryGetValue(id, out score))
    {
        score = 0;
        return false; // expected miss — not an exception
    }
    return true;
}
